import { MakeLogicType, actions, kea, path, reducers } from 'kea'

export const METRICS_DATE_RANGES = [
    { value: 1, label: 'Last hour' },
    { value: 24, label: 'Last 24 hours' },
    { value: 24 * 7, label: 'Last 7 days' },
    { value: 24 * 30, label: 'Last 30 days' },
] as const

export interface ResultsQuery {
    workflowId: string | null
    event: string | null
    windowDays: number
    revenueProperty: string | null
}

const DEFAULT_RESULTS_QUERY: ResultsQuery = { workflowId: null, event: null, windowDays: 7, revenueProperty: null }

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface transactionalMetricsFiltersLogicValues {
    hours: number
    resultsQuery: ResultsQuery
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface transactionalMetricsFiltersLogicActions {
    setHours: (hours: number) => {
        hours: number
    }
    setResultsQuery: (query: Partial<ResultsQuery>) => {
        query: Partial<ResultsQuery>
    }
}

export type transactionalMetricsFiltersLogicType = MakeLogicType<
    transactionalMetricsFiltersLogicValues,
    transactionalMetricsFiltersLogicActions
>

/** What the Metrics tab keeps while its channel changes: the period both channels show, and the email Results form. */
export const transactionalMetricsFiltersLogic = kea<transactionalMetricsFiltersLogicType>([
    path(['products', 'workflows', 'frontend', 'Transactional', 'metrics', 'transactionalMetricsFiltersLogic']),
    actions({
        setHours: (hours: number) => ({ hours }),
        setResultsQuery: (query: Partial<ResultsQuery>) => ({ query }),
    }),
    reducers({
        hours: [(24 * 7) as number, { setHours: (_, { hours }) => hours }],
        resultsQuery: [
            DEFAULT_RESULTS_QUERY as ResultsQuery,
            { setResultsQuery: (state, { query }) => ({ ...state, ...query }) },
        ],
    }),
])
